package mx.com.mesaregia.cotizaciones.integration.client;
import mx.com.mesaregia.cotizaciones.exception.*; import mx.com.mesaregia.cotizaciones.integration.dto.ClienteContext; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.util.List;
@Component public class ClienteProspectoRestAdapter implements ClienteProspectoPort {
 private final RestClient client; public ClienteProspectoRestAdapter(InternalRestClientFactory f){client=f.create(System.getenv().getOrDefault("MR_CLIENTES_BASE_URL","http://localhost:8083"));}
 @Override public ClienteContext obtener(Long id){try{var r=client.get().uri("/internal/v1/clientes-prospectos/{id}",id).retrieve().body(ClienteDto.class);if(r==null)throw new IntegrationUnavailableException("Respuesta vacía de Clientes");String nombre=((r.nombres()==null?"":r.nombres())+" "+(r.apellidos()==null?"":r.apellidos())).trim();String contacto=r.contactos()==null?null:r.contactos().stream().filter(x->x.activo()&&x.esPrincipal()).map(ContactoDto::medioContacto).findFirst().orElseGet(()->r.contactos().stream().filter(ContactoDto::activo).map(ContactoDto::medioContacto).findFirst().orElse(null));return new ClienteContext(r.id(),nombre,contacto,r.activo(),r.estado());}catch(HttpClientErrorException.NotFound e){throw new BusinessRuleException("Cliente/Prospecto no existe");}catch(ResourceAccessException|HttpServerErrorException e){throw new IntegrationUnavailableException("mr-clientes-service no disponible");}}
 private record ClienteDto(Long id,String nombres,String apellidos,String estado,boolean activo,List<ContactoDto> contactos){} private record ContactoDto(String medioContacto,boolean esPrincipal,boolean activo){}
}
